const source = $json.body ?? $json;
const allowedMaterials = new Set(['TG11', 'TG12', 'TG20', 'TG21', 'TG22', 'TG24', 'TG25']);
const errors = [];
const orderReference = String(source.orderReference ?? '').trim();
const customer = String(source.customer ?? '').trim();
const requestedDate = String(source.requestedDate ?? '').replaceAll('-', '');
const items = Array.isArray(source.items) ? source.items : [];
if (!/^[A-Z0-9-]{6,20}$/.test(orderReference)) errors.push('orderReference must contain 6-20 uppercase letters, numbers or hyphens because SAP BSTNK is limited to 20 characters');
if (!/^\d{10}$/.test(customer)) errors.push('customer must contain exactly 10 digits');
if (!/^\d{8}$/.test(requestedDate)) errors.push('requestedDate must use YYYY-MM-DD or YYYYMMDD');
if (items.length < 1 || items.length > 25) errors.push('items must contain between 1 and 25 lines');
const normalizedItems = items.map((line, index) => {
  const material = String(line.material ?? '').trim().toUpperCase();
  const quantity = Number(line.quantity);
  if (!allowedMaterials.has(material)) errors.push(`items[${index}].material is not in the approved A4H/250 catalog`);
  if (!Number.isInteger(quantity) || quantity < 1 || quantity > 9999) errors.push(`items[${index}].quantity must be an integer from 1 to 9999`);
  return { material, quantity, unit: 'PCE' };
});
return [{ json: { valid: errors.length === 0, errors, order: { orderReference, customer, requestedDate, salesOrg: '1710', channel: '10', division: '00', orderType: 'OR1', items: normalizedItems }, receivedAt: new Date().toISOString() } }];

const order = $json.order;
const escapeXml = (value) => String(value).replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;').replaceAll("'", '&apos;');
const control = `<EDI_DC40 SEGMENT='1'><TABNAM>EDI_DC40</TABNAM><DIRECT>2</DIRECT><DOCNUM></DOCNUM><MESTYP>ORDERS</MESTYP><IDOCTYP>ORDERS05</IDOCTYP><CIMTYP></CIMTYP><SNDPOR>N8NIDOC</SNDPOR><SNDPRT>LS</SNDPRT><SNDPRN>N8NIDOC</SNDPRN><RCVPOR>SAPA4H</RCVPOR><RCVPRT>LS</RCVPRT><RCVPRN>A4HCLNT250</RCVPRN></EDI_DC40>`;
const itemXml = order.items.map((line, index) => {
  const position = String((index + 1) * 10).padStart(6, '0');
  return `<E1EDP01 SEGMENT='1'><POSEX>${position}</POSEX><MENGE>${line.quantity}</MENGE><MENEE>PCE</MENEE><E1EDP19 SEGMENT='1'><QUALF>002</QUALF><IDTNR>${escapeXml(line.material)}</IDTNR></E1EDP19><E1EDP20 SEGMENT='1'><WMENG>${line.quantity}</WMENG><EDATU>${order.requestedDate}</EDATU></E1EDP20></E1EDP01>`;
}).join('');
const idocXml = `<ORDERS05><IDOC BEGIN='1'>${control}<E1EDK01 SEGMENT='1'><ACTION>001</ACTION></E1EDK01><E1EDK14 SEGMENT='1'><QUALF>006</QUALF><ORGID>${order.division}</ORGID></E1EDK14><E1EDK14 SEGMENT='1'><QUALF>007</QUALF><ORGID>${order.channel}</ORGID></E1EDK14><E1EDK14 SEGMENT='1'><QUALF>008</QUALF><ORGID>${order.salesOrg}</ORGID></E1EDK14><E1EDK14 SEGMENT='1'><QUALF>012</QUALF><ORGID>${order.orderType}</ORGID></E1EDK14><E1EDK03 SEGMENT='1'><IDDAT>002</IDDAT><DATUM>${order.requestedDate}</DATUM></E1EDK03><E1EDKA1 SEGMENT='1'><PARVW>AG</PARVW><PARTN>${order.customer}</PARTN></E1EDKA1><E1EDK02 SEGMENT='1'><QUALF>001</QUALF><BELNR>${escapeXml(order.orderReference)}</BELNR><DATUM>20260822</DATUM></E1EDK02>${itemXml}</IDOC></ORDERS05>`;
const idempotencyKey = `A4H250-B2B-${order.orderReference}-v1`;
return [{ json: { ...$json, idempotencyKey, writeConfirmation: `SEND submitPurchaseOrderIdoc ${idempotencyKey}`, idocXml } }];
